// Every positive encounter below inherits the actual zero-XP production route. The action controller
// is explicit engineering input; it is not human play, language assessment or a balance certificate.
public static class OptionalEncounterCases
{
    private static readonly Mist.Core.Content.RuntimeCatalog Catalog=Q102.Q102Cases.Catalog();
    private static string Root=>Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../.."));
    public static OptionalContractPackage Package()=>OptionalContractPackage.Parse(File.ReadAllText(Path.Combine(Root,"content/source/optional_encounter_contracts/learner_package.json")));
    private static ProfileStore Store(string label)=>new(Path.Combine(Environment.GetEnvironmentVariable("MISTSEA_TEST_OUTPUT")??Path.GetTempPath(),"optional-contract-"+label+"-"+Guid.NewGuid()),Catalog.ReleaseId);
    private static void Success(CommandResult result)=>Require(result.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,StrictJson.Serialize(result));
    private static ActorState Actor(ProfileStore store)=>StrictJson.Deserialize<ActorState>(Done(store.SnapshotAsync()).Entities.Single(e=>e.Id=="actor").Json);
    private static string World(BranchSnapshot s)=>StrictJson.Serialize(new{entities=s.Entities.Where(e=>e.Id!="actor"&&!e.Id.StartsWith("optional-encounter:",StringComparison.Ordinal)&&!OptionalContractRules.Ids.Any(id=>e.Id=="combat:"+id)).OrderBy(e=>e.Id),items=s.Items.OrderBy(i=>i.Id),balances=s.Balances.OrderBy(b=>b.Key)});
    public sealed record Entry(OptionalEncounterService Service,Action<Point2> Walk);
    public static Entry ActualEntry(ProfileStore store,string region)
    {
        var package=Package();ImmutableDictionary<string,SceneGeometry> geometry;Action<Point2> walk;
        if(region=="R1")
        {var main=FirstApproaches.FirstApproachCases.ActualTowerEntry(store);geometry=main.Geometry;walk=to=>Done(main.MoveAsync(new NavigationGrid(main.Geometry[Actor(store).Scene]).FindPath(Actor(store).Position,to,true)));var outPort=main.Geometry["R1-S09"].Ports.Single(p=>p.TargetScene=="R1-S02");walk(outPort.Stand);Success(Done(main.EnterPortAsync(outPort.Id)));Success(Done(new PartyService(store,Catalog).BuyConsumableAsync("CON-04",new(Guid.NewGuid()))));var back=main.Geometry["R1-S02"].Ports.Single(p=>p.TargetScene=="R1-S09");walk(back.Stand);Success(Done(main.EnterPortAsync(back.Id)));}
        else if(region=="R2")
        {var p=ChapterTwo.ChapterTwoCases.NormalComplete(store);var main=p.Service;geometry=Done(main.CurrentGeometryAsync());Navigate(store,geometry,"R2-S06",main.PortIssue,path=>Done(main.TraverseAsync(path)),id=>Done(main.EnterPortAsync(id)));walk=to=>Done(main.TraverseAsync(new NavigationGrid(Done(main.CurrentGeometryAsync())[Actor(store).Scene]).FindPath(Actor(store).Position,to,true)));}
        else if(region=="R3")
        {var p=ChapterThree.ChapterThreeCases.ActualArrival(store);var run=new ChapterThree.ChapterThreeCases.Run(store,p.Service);run.Node301();run.Goto("R3-S05");run.Walk(run.View.Geometry["R3-S05"].Ports.Single(port=>port.TargetScene=="R3-O02").Stand);var side=new SideWellObservationService(store,Catalog,p.Service.Package);Success(Done(side.InspectEntryAsync()));Success(Done(side.RegisterEntrySafetyAsync()));var entered=Done(side.EnterPortAsync("R3-S05.to.R3-O02"));Success(entered);Success(Done(side.RecordWalkedRouteAsync(entered.Receipt!.Id.Value.ToString())));geometry=Done(p.Service.CurrentGeometryAsync());walk=run.Walk;}
        else if(region=="R4")
        {var p=ChapterFour.ChapterFourCases.NormalComplete(store);var run=new ChapterFour.ChapterFourCases.Run(store,p.Service);run.Goto("R4-S07");geometry=Done(p.Service.CurrentGeometryAsync());walk=run.Walk;}
        else if(region=="R5")
        {var p=ChapterFive.ChapterFiveCases.ActualArrival(store);var run=new ChapterFive.ChapterFiveCases.Run(store,p.Service);run.Node501(true);run.Goto("R5-S04");geometry=Done(p.Service.CurrentGeometryAsync());walk=run.Walk;}
        else if(region=="R6")
        {var p=ChapterSix.ChapterSixCases.ActualArrival(store);var run=new ChapterSix.ChapterSixCases.Run(store,p.Service,p.Interior);run.Node601();run.RidgeReady();run.Goto("R6-S06");geometry=Done(p.Service.CurrentGeometryAsync());walk=to=>Done(p.Service.TraverseAsync(new NavigationGrid(Done(p.Service.CurrentGeometryAsync())[Actor(store).Scene]).FindPath(Actor(store).Position,to,true)));}
        else throw new InvalidOperationException("Unregistered optional region.");
        return new(new(store,store,Catalog,package,geometry),walk);
    }
    private static void Navigate(ProfileStore s,ImmutableDictionary<string,SceneGeometry> geometry,string target,Func<BranchSnapshot,Port,string?> gate,Action<ImmutableArray<Point2>> move,Func<string,CommandResult> enter)
    {
        var start=Actor(s);var snap=Done(s.SnapshotAsync());var queue=new Queue<string>();queue.Enqueue(start.Scene);var previous=new Dictionary<string,string?>{{start.Scene,null}};
        while(queue.TryDequeue(out var current)){if(current==target)break;foreach(var port in geometry[current].Ports){if(!geometry.ContainsKey(port.TargetScene)||previous.ContainsKey(port.TargetScene))continue;var projected=snap with{Entities=snap.Entities.Select(e=>e.Id=="actor"?e with{Json=StrictJson.Serialize(start with{Scene=current})}:e).ToImmutableArray()};if(gate(projected,port)is not null)continue;previous[port.TargetScene]=current;queue.Enqueue(port.TargetScene);}}
        Require(previous.ContainsKey(target),"Actual optional arena has no permitted route: "+target);var path=new List<string>();for(string? next=target;previous[next!]is{}from;next=from)path.Add(next!);path.Reverse();foreach(string next in path){var a=Actor(s);var port=geometry[a.Scene].Ports.Single(p=>p.TargetScene==next);move(new NavigationGrid(geometry[a.Scene]).FindPath(a.Position,port.Stand,true));Success(enter(port.Id));}
    }
    private static void Spot(Entry entry,string id){var c=entry.Service.Package.Contracts.Single(c=>c.Id==id);entry.Walk(entry.Service.Geometry[c.Scene].Spots.Single(s=>s.Id==c.Spot).Stand);}
    public static void Control(OptionalEncounterService service,string id)
    {
        for(int count=0;count<900&&Done(service.EncounterAsync(id))!.Battle.Outcome==CombatOutcome.Active;count++)
        {var state=Done(service.EncounterAsync(id))!;var request=BattleCandidate.Choose(new(service.BattleDefinitions,state.Battle));var preview=Done(service.PreviewActionAsync(id,request));Require(preview.Action.Legal,preview.Description);Success(Done(service.ConfirmAsync(preview.Token)));}
        Require(Done(service.EncounterAsync(id))!.Battle.Outcome==CombatOutcome.Controlled,"Actual shared combat failed: "+id);
    }
    private static void ExportEntry(ProfileStore s,Entry entry,string region)
    {
        // Native driver input is an actual SQLite backup made before either additional source is acquired.
        var backup=Done(s.BackupAsync());var snap=Done(s.SnapshotAsync());string output=Environment.GetEnvironmentVariable("MISTSEA_TEST_OUTPUT")??Path.GetTempPath();string target=Path.GetFullPath(Path.Combine(output,"normal-optional-"+region.ToLowerInvariant()+"-native-entry"));Require(!Directory.Exists(target),"Native entry path must be new and isolated.");
        // Keep the real control pointer unchanged. Inventory migration or recovery
        // can make MainPath a file under recovery/ rather than profile.sqlite.
        // Place the consistent online backup at that same relative generation.
        string relativeMain=Path.GetRelativePath(s.RootPath,s.MainPath);Require(!Path.IsPathRooted(relativeMain)&&relativeMain!=".."&&!relativeMain.StartsWith(".."+Path.DirectorySeparatorChar,StringComparison.Ordinal),"Actual managed generation escaped its profile.");
        string targetMain=Path.GetFullPath(Path.Combine(target,relativeMain));Require(targetMain.StartsWith(target+Path.DirectorySeparatorChar,OperatingSystem.IsWindows()?StringComparison.OrdinalIgnoreCase:StringComparison.Ordinal),"Native generation copy escaped its isolated target.");Directory.CreateDirectory(Path.GetDirectoryName(targetMain)!);File.Copy(backup.Path,targetMain);File.Copy(s.ControlPath,Path.Combine(target,"control.sqlite"));
        string oldMain=Path.Combine(s.RootPath,"profile.sqlite");if(File.Exists(oldMain)&&!string.Equals(oldMain,s.MainPath,OperatingSystem.IsWindows()?StringComparison.OrdinalIgnoreCase:StringComparison.Ordinal))File.Copy(oldMain,Path.Combine(target,"profile.sqlite"));
        foreach(string folder in new[]{"checkpoints","backups","recovery"}){string source=Path.Combine(s.RootPath,folder);if(!Directory.Exists(source))continue;foreach(string file in Directory.EnumerateFiles(source,"*",SearchOption.AllDirectories)){if(string.Equals(Path.GetFullPath(file),s.MainPath,OperatingSystem.IsWindows()?StringComparison.OrdinalIgnoreCase:StringComparison.Ordinal))continue;string copy=Path.Combine(target,Path.GetRelativePath(s.RootPath,file));Directory.CreateDirectory(Path.GetDirectoryName(copy)!);File.Copy(file,copy);}}
        using(var copied=new ProfileStore(target,Catalog.ReleaseId)){var a=Done(copied.SnapshotAsync());Require(Path.GetRelativePath(target,copied.MainPath)==relativeMain&&StrictJson.Serialize(a)==StrictJson.Serialize(snap),"Native copy must use the same real active generation and exact current entry snapshot.");Require(a.Sequence==backup.Sequence&&(a.Balances.GetValueOrDefault("experience")>0)&&a.Entities.All(e=>!e.Id.StartsWith("optional-encounter:",StringComparison.Ordinal))&&a.Receipts.All(r=>r.ActionType is not("explicit_engineering_fixture" or "internal_slice_initialization")&&!r.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)));}
        File.WriteAllText(Path.Combine(target,"normal-optional-"+region.ToLowerInvariant()+"-native-entry.json"),StrictJson.Serialize(new{scope="actual zero-XP normal preceding route, original local gates and protected cargo/sidewell entry; both optional sources, permits, encounters and results untouched",region,profile_path=targetMain,active_generation=relativeMain,actor=Actor(s),source_backup_sha256=backup.Sha256,source_version=entry.Service.Package.ContentVersion,receipts=snap.Receipts,experience=snap.Balances["experience"],human_play="not_run",language_review="human_pending",balance_review="human_pending"}));
    }
    public static void Register()
    {
        Add("CX-044","twelve_optional_contracts_preserve_canonical_slots_full_sources_and_all_original_geometry",()=>
        {var p=Package();Require(p.Contracts.Length==12&&p.Materials.Length==12&&p.Materials.Sum(m=>m.Paragraphs.Length)==36&&p.Materials.All(m=>m.Paragraphs.Sum(p=>p.En.Split(' ',StringSplitOptions.RemoveEmptyEntries).Length)>150));var geometry=Campaign.CampaignCases.Package().Scenes.ToImmutableDictionary(s=>s.Id).SetItems(ChapterOne.ChapterOneCases.Package().Scenes.ToDictionary(s=>s.Id)).SetItems(ChapterTwo.ChapterTwoCases.Package().Scenes.ToDictionary(s=>s.Geometry.Id,s=>s.Geometry)).SetItems(ChapterThree.ChapterThreeCases.Package().Scenes.ToDictionary(s=>s.Geometry.Id,s=>s.Geometry)).SetItems(ChapterFour.ChapterFourCases.Package().Scenes.ToDictionary(s=>s.Geometry.Id,s=>s.Geometry)).SetItems(ChapterFive.ChapterFiveCases.Package().Scenes.ToDictionary(s=>s.Geometry.Id,s=>s.Geometry)).SetItems(ChapterSix.ChapterSixCases.Package().Scenes.ToDictionary(s=>s.Geometry.Id,s=>s.Geometry));var extended=OptionalContractRules.ExtendGeometry(p,geometry);foreach(string scene in OptionalContractRules.Arenas.Values){Require(extended[scene].Ports.SequenceEqual(geometry[scene].Ports)&&extended[scene].Blocked.SequenceEqual(geometry[scene].Blocked)&&extended[scene].Danger.SequenceEqual(geometry[scene].Danger)&&extended[scene].Spots.Length==geometry[scene].Spots.Length+2);}Throws<InvalidDataException>(()=>OptionalContractRules.Validate(p with{HumanReview="passed"}));Throws<InvalidDataException>(()=>OptionalContractRules.Validate(p with{Contracts=p.Contracts.SetItem(1,p.Contracts[1]with{Target=p.Contracts[0].Target})}));Throws<InvalidDataException>(()=>OptionalContractRules.ExtendGeometry(p with{ExtraSpots=p.ExtraSpots.SetItem(0,p.ExtraSpots[0]with{Spot=p.ExtraSpots[0].Spot with{Stand=new(500,500)}})},geometry));});
        Add("CX-044","bare_actor_cannot_acquire_optional_contract_source_or_mint_permission_and_main_work_does_not_implicitly_accept",()=>
        {using var s=Store("negative-bare");var p=Package();var c=p.Contracts[0];var geo=ChapterOne.ChapterOneCases.Package().Scenes.ToImmutableDictionary(x=>x.Id);var service=new OptionalEncounterService(s,s,Catalog,p,geo);Mist.Tests.NPC.NpcCases.Fixture(s,"fixture:negative-only-bare-actor","explicit_engineering_fixture",new{scope="invalid actor negative; not a played entry"},[Mist.Tests.NPC.NpcCases.Entity(s,"actor","actor",new ActorState(c.Scene,service.Geometry[c.Scene].Spots.Single(x=>x.Id==c.Spot).Stand,0))]);long seq=s.Session.Sequence;Throws<InvalidOperationException>(()=>Done(service.DiscoverAsync(c.Material)));Throws<InvalidOperationException>(()=>Done(service.AcceptContractAsync(c.Id)));Throws<InvalidOperationException>(()=>Done(service.BeginAsync(c.Id)));Require(s.Session.Sequence==seq&&Done(service.PermitAsync(c.Id))is null);});
        foreach(string region in OptionalContractRules.Regions)
        {string captured=region;Add("CP-"+region+"-03","normal_zero_XP_"+region+"_both_independent_optional_contracts_actual_control_inspection_CAS_and_no_rewards",()=>NormalRegion(captured));}
    }
    private static void NormalRegion(string region)
    {
        using var s=Store(region);var entry=ActualEntry(s,region);var service=entry.Service;var definitions=service.Package.Contracts.Where(c=>c.Region==region).ToArray();Spot(entry,definitions[0].Id);ExportEntry(s,entry,region);var original=Done(s.SnapshotAsync());string world=World(original);Require(original.Receipts.All(r=>r.ActionType is not("explicit_engineering_fixture" or "internal_slice_initialization")&&!r.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)));
        for(int index=0;index<2;index++)
        {
            var c=definitions[index];Spot(entry,c.Id);long seq=s.Session.Sequence;Throws<InvalidOperationException>(()=>Done(service.BeginAsync(c.Id)));Throws<InvalidOperationException>(()=>Done(service.AcceptContractAsync(c.Id)));Require(s.Session.Sequence==seq);Success(Done(service.DiscoverAsync(c.Material)));Require(Done(service.OpenMaterialAsync(c.Material))==service.Package.Materials.Single(m=>m.Id==c.Material));Throws<InvalidOperationException>(()=>Done(service.BeginAsync(c.Id)));Success(Done(service.AcceptContractAsync(c.Id)));string[] carried=region=="R1"&&index==0?[Done(s.SnapshotAsync()).Items.Single(i=>i.OwnerKind=="player"&&i.OwnerId=="hero"&&i.DefinitionId=="CON-04").Id]:[];Success(Done(service.BeginAsync(c.Id,supplies:carried)));var began=Done(service.EncounterAsync(c.Id))!;var permit=Done(service.PermitAsync(c.Id))!;Require(began.Battle.Units.Count(u=>u.Side==CombatSide.Ally)==3&&began.Battle.Units.Where(u=>u.Side==CombatSide.Enemy).Select(u=>u.Id).SequenceEqual(c.Enemies.Select(e=>e.Id)));Throws<InvalidOperationException>(()=>Done(service.InspectTargetAsync(c.Id,c.InspectionAction)));
            var request=carried.Length>0?new BattleRequest(new(Guid.NewGuid()),"SUPPLY",began.Battle.CurrentActor!,[began.Battle.CurrentActor!],Device:carried[0]):BattleCandidate.Choose(new(service.BattleDefinitions,began.Battle));seq=s.Session.Sequence;var preview=Done(service.PreviewActionAsync(c.Id,request));Require(preview.Action.Legal&&s.Session.Sequence==seq);service.ClosePreview(preview.Token);Require(Done(service.ConfirmAsync(preview.Token)).Status==CommitStatus.Rejected&&s.Session.Sequence==seq);
            preview=Done(service.PreviewActionAsync(c.Id,request));var competing=Done(service.PreviewActionAsync(c.Id,request with{Command=new(Guid.NewGuid())}));Require(competing.Action.Legal);Success(Done(service.ConfirmAsync(preview.Token)));Require(Done(service.ConfirmAsync(preview.Token)).Status==CommitStatus.AlreadyCommitted);seq=s.Session.Sequence;Require(Done(service.ConfirmAsync(competing.Token)).Status==CommitStatus.Rejected&&s.Session.Sequence==seq);if(carried.Length>0)Require(Done(s.SnapshotAsync()).Items.Single(i=>i.Id==carried[0]).OwnerKind=="consumed");string continued=StrictJson.Serialize(Done(service.EncounterAsync(c.Id)));Done(s.ContinueAsync());Require(StrictJson.Serialize(Done(service.EncounterAsync(c.Id)))==continued);var current=Done(service.EncounterAsync(c.Id))!;var stale=Done(service.PreviewActionAsync(c.Id,BattleCandidate.Choose(new(service.BattleDefinitions,current.Battle))));Require(stale.Action.Legal);Success(Done(service.WithdrawAsync(c.Id)));Require(Done(service.ConfirmAsync(stale.Token)).Status==CommitStatus.Rejected);var withdrew=Done(service.EncounterAsync(c.Id))!;Require(withdrew.Battle.Outcome==CombatOutcome.Withdrawn&&withdrew.Battle.Units.Select(u=>(u.Id,u.Hp,u.Focus)).SequenceEqual(began.Entry.Units.Select(u=>(u.Id,u.Hp,u.Focus)))&&Done(service.OpenMaterialAsync(c.Material)).ContentVersion==OptionalContractRules.Version);if(carried.Length>0)Require(Done(s.SnapshotAsync()).Items.Single(i=>i.Id==carried[0])is{OwnerKind:"player",OwnerId:"hero"});Success(Done(service.BeginAsync(c.Id)));var resumed=Done(service.EncounterAsync(c.Id))!;Require(resumed.Battle.Instance==began.Battle.Instance&&resumed.Battle.Attempt!=began.Battle.Attempt&&Done(service.PermitAsync(c.Id))!.Instance==permit.Instance);
            if(index==0)
            {current=Done(service.EncounterAsync(c.Id))!;var revoked=Done(service.PreviewActionAsync(c.Id,BattleCandidate.Choose(new(service.BattleDefinitions,current.Battle))));Require(revoked.Action.Legal);Success(Done(service.RevokeContractAsync(c.Id)));seq=s.Session.Sequence;Require(Done(service.ConfirmAsync(revoked.Token)).Status==CommitStatus.Rejected&&s.Session.Sequence==seq&&Done(service.PermitAsync(c.Id))is{Allowed:false}&&Done(service.EncounterAsync(c.Id))!.Battle.Outcome==CombatOutcome.Withdrawn);Throws<InvalidOperationException>(()=>Done(service.BeginAsync(c.Id)));Success(Done(service.AcceptContractAsync(c.Id)));Success(Done(service.BeginAsync(c.Id)));}
            else
            {current=Done(service.EncounterAsync(c.Id))!;var oldLoad=Done(service.PreviewActionAsync(c.Id,BattleCandidate.Choose(new(service.BattleDefinitions,current.Battle))));Require(oldLoad.Action.Legal);Done(s.ContinueAsync());seq=s.Session.Sequence;Require(Done(service.ConfirmAsync(oldLoad.Token)).Status==CommitStatus.Rejected&&s.Session.Sequence==seq);}
            Control(service,c.Id);Require(Done(service.ResultAsync(c.Id))is null);seq=s.Session.Sequence;Throws<InvalidOperationException>(()=>Done(service.InspectTargetAsync(c.Id,definitions[1-index].InspectionAction)));Require(s.Session.Sequence==seq);Success(Done(service.InspectTargetAsync(c.Id,c.InspectionAction)));seq=s.Session.Sequence;Require(Done(service.InspectTargetAsync(c.Id,c.InspectionAction)).Status==CommitStatus.AlreadyCommitted&&s.Session.Sequence==seq);var result=Done(service.ResultAsync(c.Id))!;Require(result is{Controlled:true,Inspected:true,Experience:0,Marks:0,Parts:0}&&result.ContractInstance==permit.Instance&&result.Target==c.Target&&result.SourceFingerprint==OptionalContractRules.Fingerprint(service.Package.Materials.Single(m=>m.Id==c.Material))&&Done(s.SnapshotAsync()).Receipts.Count(r=>r.SemanticKey=="optional-contract:"+c.Id+":result")==1);Throws<InvalidOperationException>(()=>Done(service.BeginAsync(c.Id)));Throws<InvalidOperationException>(()=>Done(service.WithdrawAsync(c.Id)));Done(s.ContinueAsync());Require(Done(service.ResultAsync(c.Id))==result);Require(World(Done(s.SnapshotAsync()))==world,"Independent optional contract changed mainline entities, actual items or balances.");
        }
        var final=Done(s.SnapshotAsync());File.WriteAllText(Path.Combine(s.RootPath,"normal-optional-"+region.ToLowerInvariant()+"-results.json"),StrictJson.Serialize(new{scope="actual zero-XP inherited production navigation plus two independent source/consent/shared-combat/target inspection results; explicit engineering action controller",region,results=definitions.Select(c=>Done(service.ResultAsync(c.Id))),experience=final.Balances["experience"],additional_reward=0,receipts=final.Receipts.Where(r=>r.ActionType.StartsWith("optional_contract",StringComparison.Ordinal)),human_play="not_run",language_review="human_pending",numeric_review="human_pending"}));
    }
